import 'bootstrap/dist/css/bootstrap.min.css';
import { Component } from 'react';

class App extends Component {
  constructor(props) {
    super(props)
    this.state = {
      deseos:["Gambas","Jamón"]
    }
  }

  handleAniadirDeseo(event) {
    event.preventDefault();
    // let aux = this.state.deseos.slice()
    let aux = JSON.parse(JSON.stringify(this.state.deseos));
    aux.push(event.target.deseo.value);
    this.setState({deseos: aux});

    /*
    Para cambiar el estado, tengo que hacer 3 cosas:

      1. Hago una copia.
      2. Modifico la copia.
      3. Actualizo el estado con setState.
    */
  }

  render() {
    return (
      <div className="App">
        <h1>LISTA DE DESEOS</h1>
        <div>
         <p><strong>Añade tu regalo favorito</strong></p>
       </div>
      <DesireList deseo={this.state.deseos}/>
      <Desire onAddDeseo={this.handleAniadirDeseo.bind(this)}/>
      </div>
    );
  }
}

class DesireList extends Component{
  render(){
    return(
      <ul>
        <li>{this.props.deseo.join(" - ")}</li>
      </ul>
    )
  }
}
class Desire extends Component{
  render(){
    return(
      <form onSubmit={this.handleAniadirDeseo}>
        <input type="text" placeholder='Escribe tu deseo' name="deseo"/>
      </form>
    )
  }
}

export default App;
